package leobog

import (
	"bytes"
	"embed"
	"encoding/hex"
	"encoding/json"
)

// The other BY-520 keyboards, generated by scripts/genkeyboards.ts from Let
// Me Drive's tables, which come from the vendors' drivers. None has been
// tried: their effect lists are a template the vendors copy between models
// (the Hi75's row lists effects it lacks), and their factory keys are not
// known, so they get lighting and per-key colors but no remaps or reset.
//
//go:embed data/models.json
var dataFS embed.FS

// catalogCustom is the per-key effect's ID on these firmwares, as Let Me Drive
// writes it; the Hi75 recorded with the official driver uses 21.
const catalogCustom = 18

type rawModel struct {
	Name       string   `json:"name"`
	VID        uint16   `json:"vid"`
	PID        uint16   `json:"pid"`
	Ident      string   `json:"ident"`
	Effects    []Effect `json:"effects"`
	Brightness []int    `json:"brightness"`
	Speed      []int    `json:"speed"`
	FnIndex    int      `json:"fnIndex"`
	Width      int      `json:"width"`
	Height     int      `json:"height"`
	Keys       []Key    `json:"keys"`
}

// Models are the keyboards this package drives; the first is the one scenes
// offer the effects of when no keyboard is connected.
var Models = append([]*Model{hi75}, catalog(hi75)...)

// catalog loads the table, leaving out the keyboards described by hand.
func catalog(known ...*Model) []*Model {
	b, err := dataFS.ReadFile("data/models.json")
	if err != nil {
		panic(err)
	}
	var raw []rawModel
	if err := json.Unmarshal(b, &raw); err != nil {
		panic(err)
	}
	var out []*Model
next:
	for _, r := range raw {
		ident, err := hex.DecodeString(r.Ident)
		if err != nil || len(ident) != 6 {
			panic("leobog: bad model number " + r.Ident)
		}
		for _, k := range known {
			if k.VID == r.VID && k.PID == r.PID && bytes.Equal(k.ident, ident) {
				continue next
			}
		}
		m := &Model{Name: r.Name, VID: r.VID, PID: r.PID, ident: ident, Layout: r.Keys, Width: r.Width, Height: r.Height,
			FnIndex: r.FnIndex, custom: catalogCustom, brightness: r.Brightness, speed: r.Speed}
		for _, e := range r.Effects {
			// The palette has colors for effects 1–13 only; a later one can only cycle colors.
			e.Color = e.Color && e.ID < paletteEffects
			m.Effects = append(m.Effects, e)
		}
		m.Effects = append(m.Effects, Effect{EffectCustom, "custom", false, false}, Effect{EffectOff, "off", false, false})
		out = append(out, m)
	}
	return out
}
